// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address actor, uint256 amount, uint256 existingBalance) public {
        vm.assume(actor != address(0));
        vm.assume(amount < type(uint256).max - existingBalance);
        vm.deal(actor, existingBalance + amount);
        vm.prank(actor);
        c.addToBalance{value: existingBalance}();
        uint256 beforeBalance = c.getBalance(actor);
        assertEq(beforeBalance, existingBalance, "setup failed");
        vm.prank(actor);
        c.addToBalance{value: amount}();
        uint256 afterBalance = c.getBalance(actor);
        assertEq(afterBalance, beforeBalance + amount);
    }
}
